import{_ as a,o as i,c as n,a2 as t}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Blacksmithing","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/professions/blacksmithing.md","filePath":"en/game-design/professions/blacksmithing.md"}'),s={name:"en/game-design/professions/blacksmithing.md"};function o(r,e,l,d,c,h){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="blacksmithing" tabindex="-1">Blacksmithing <a class="header-anchor" href="#blacksmithing" aria-label="Permalink to &quot;Blacksmithing&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; all mechanics, examples and technique paths below remain candidates. <strong>Implementation:</strong> no implementation of this redesign is established by this documentation batch. <strong>Availability:</strong> not established. <strong>Verification:</strong> documentation review only; no gameplay test. <strong>Reviewed:</strong> 2026-10-09 for public projection; design status and mechanics preserved from the canonical specification.</p><p><a href="/Syrolands-Public/en/guide/professions/blacksmithing.html">Player-facing overview</a> · <a href="/Syrolands-Public/en/game-design/professions/profession-system.html">Profession System</a></p><h2 id="purpose-and-profession-loop" tabindex="-1">Purpose and profession loop <a class="header-anchor" href="#purpose-and-profession-loop" aria-label="Permalink to &quot;Purpose and profession loop&quot;">​</a></h2><p>Blacksmithing should be metallurgy and metal transformation, not &quot;ingots -&gt; item&quot;.</p><h3 id="core-chain" tabindex="-1">Core chain <a class="header-anchor" href="#core-chain" aria-label="Permalink to &quot;Core chain&quot;">​</a></h3><p>Smelting -&gt; Refining -&gt; Alloying -&gt; Shaping/Forging -&gt; Heat Treatment -&gt; Finishing -&gt; Maintenance</p><h3 id="possible-stages" tabindex="-1">Possible stages <a class="header-anchor" href="#possible-stages" aria-label="Permalink to &quot;Possible stages&quot;">​</a></h3><ul><li>ore smelting;</li><li>crude bloom/crude metal;</li><li>refining impurities;</li><li>alloying;</li><li>forge shaping;</li><li>heat treatment;</li><li>finishing.</li></ul><h3 id="material-and-process-influences" tabindex="-1">Material and process influences <a class="header-anchor" href="#material-and-process-influences" aria-label="Permalink to &quot;Material and process influences&quot;">​</a></h3><ul><li>hardness;</li><li>toughness;</li><li>flexibility;</li><li>weight;</li><li>wear;</li><li>cutting/penetration/blunt behavior.</li></ul><p>Do not turn these into dozens of exposed stats.</p><h3 id="forging-interface" tabindex="-1">Forging interface <a class="header-anchor" href="#forging-interface" aria-label="Permalink to &quot;Forging interface&quot;">​</a></h3><ul><li>forge/fire;</li><li>anvil;</li><li>quench;</li><li>tools;</li><li>work zones/shape operations.</li></ul><h3 id="potential-forging-operations" tabindex="-1">Potential forging operations <a class="header-anchor" href="#potential-forging-operations" aria-label="Permalink to &quot;Potential forging operations&quot;">​</a></h3><ul><li>draw;</li><li>flatten;</li><li>taper;</li><li>bend;</li><li>punch;</li><li>fuller.</li></ul><h3 id="heat-treatment" tabindex="-1">Heat treatment <a class="header-anchor" href="#heat-treatment" aria-label="Permalink to &quot;Heat treatment&quot;">​</a></h3><ul><li>quenching;</li><li>tempering;</li><li>annealing;</li><li>other techniques if later justified.</li></ul><h3 id="tradeoffs-matter" tabindex="-1">Tradeoffs matter <a class="header-anchor" href="#tradeoffs-matter" aria-label="Permalink to &quot;Tradeoffs matter&quot;">​</a></h3><ul><li>harder edge vs brittleness;</li><li>toughness vs peak cutting;</li><li>weight vs durability;</li></ul><p>etc.</p><p>Exceptional quality should emerge from process/material/skill, not a simple random &quot;Exceptional&quot; roll.</p><h3 id="field-utility" tabindex="-1">Field utility <a class="header-anchor" href="#field-utility" aria-label="Permalink to &quot;Field utility&quot;">​</a></h3><ul><li>equipment assessment;</li><li>field maintenance;</li><li>sharpening;</li><li>minor repair;</li><li>structural/material knowledge.</li></ul><h3 id="cross-skill" tabindex="-1">Cross-skill <a class="header-anchor" href="#cross-skill" aria-label="Permalink to &quot;Cross-skill&quot;">​</a></h3><ul><li>Arms Lore = martial understanding of how a weapon performs;</li><li>Blacksmithing = material/structural understanding;</li><li>together provide richer assessment.</li></ul><h2 id="knowledge-and-specialization" tabindex="-1">Knowledge and specialization <a class="header-anchor" href="#knowledge-and-specialization" aria-label="Permalink to &quot;Knowledge and specialization&quot;">​</a></h2><p><strong>Metallurgical Journal.</strong> Bladesmithing and Armorsmithing are concrete technique examples. Materials, process understanding and practice can create durable-field-weapon or lightweight-armor identities.</p><h2 id="shared-progression-production-and-economy" tabindex="-1">Shared progression, production and economy <a class="header-anchor" href="#shared-progression-production-and-economy" aria-label="Permalink to &quot;Shared progression, production and economy&quot;">​</a></h2><p>The <a href="/Syrolands-Public/en/game-design/characters/skills-and-skillcap.html">character skill framework</a> owns teaching and cap/gain direction. The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html">Profession System</a> owns craft discovery, knowledge sharing, manual mastery, batch production, commissions and multidimensional reputation. Those rules are not independently redefined here. The <a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html">quality specification</a> owns the shared result envelope and rare item properties.</p><h2 id="related-skills-and-field-interactions" tabindex="-1">Related skills and field interactions <a class="header-anchor" href="#related-skills-and-field-interactions" aria-label="Permalink to &quot;Related skills and field interactions&quot;">​</a></h2><p>Mining supplies geological provenance; Arms Lore contributes martial use knowledge while Blacksmithing contributes material/structural assessment. Carpentry and Tailoring can contribute composite components; Tinkering may need frames and armor.</p><p><a href="/Syrolands-Public/en/game-design/professions/mining.html">Mining</a> · <a href="/Syrolands-Public/en/game-design/skills-and-knowledge.html">Arms Lore and skill roles</a> · <a href="/Syrolands-Public/en/game-design/equipment-and-loot.html">Equipment and loot</a> · Armor adapter · <a href="/Syrolands-Public/en/game-design/professions/carpentry.html">Carpentry</a>.</p><h2 id="abstraction-and-technical-boundary" tabindex="-1">Abstraction and technical boundary <a class="header-anchor" href="#abstraction-and-technical-boundary" aria-label="Permalink to &quot;Abstraction and technical boundary&quot;">​</a></h2><p>Keep only state and feedback that support meaningful decisions. The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html#performance-abstraction-and-authority">shared abstraction/authority constraints</a> and living-world architecture apply; persistence requires a separate technical design. Nothing here selects packet IDs, schemas, timers, UI assets or runtime algorithms.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>Material families and alloy recipes; meaningful process windows; heat-treatment feedback; repair limits and material costs; assessment information boundaries; how compact quality dimensions map onto armor/weapon performance. No new absorption formula or Exceptional roll is selected.</p><p>The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">shared reconciliation register</a> owns cross-system conflicts. Existing combat experiments and evidence do not validate this profession redesign.</p>',38)])])}const u=a(s,[["render",o]]);export{p as __pageData,u as default};
